let action = 'unknown';
if (text.includes('confirme') || text === '✅' || text === '1') action = 'confirm';
else if (text.includes('annuler') || text === '❌' || text === '2') action = 'cancel';
else if (text.includes('modifier') || text === '🔄' || text === '3') action = 'modify';
return [{json: {
  phone: msg.from || msg.wa_id || '',
  action: action,
  raw_message: text,
  timestamp: new Date().toISOString()
}}];

