const msg = $input.first().json;
const text = (msg.messages?.[0]?.text?.body || msg.messages?.[0]?.button?.reply?.title || '').trim();
const phone = msg.messages?.[0]?.from || msg.contacts?.[0]?.wa_id || '';
const name = msg.contacts?.[0]?.profile?.name || '';

// Quick menu detection
let intent = 'free_text';
if (['1', 'réserver', 'reservation', 'book'].some(k => text.toLowerCase().includes(k))) intent = 'reserve';
else if (['2', 'menu', 'carte'].some(k => text.toLowerCase().includes(k))) intent = 'menu';
else if (['3', 'commander', 'emporter', 'takeaway'].some(k => text.toLowerCase().includes(k))) intent = 'order';
else if (['4', 'horaire', 'heure', 'ouvert', 'adresse', 'où'].some(k => text.toLowerCase().includes(k))) intent = 'info';
else if (['5', 'parler', 'humain', 'quelqu'].some(k => text.toLowerCase().includes(k))) intent = 'human';
else if (['points', 'fidélité', 'loyalty', 'statut'].some(k => text.toLowerCase().includes(k))) intent = 'loyalty';
else if (['annuler', 'cancel'].some(k => text.toLowerCase().includes(k))) intent = 'cancel';
else if (['stop'].some(k => text.toLowerCase() === k)) intent = 'unsubscribe';

return [{json: {phone, name, text, intent, timestamp: new Date().toISOString()}}];

const items = $input.all().map(i => i.json.fields || i.json);
let menu = '🍽️ *Menu La Tavola* 🇮🇹\n\n';
const categories = {};
items.forEach(item => {
  const cat = item.category || 'Autre';
  if (!categories[cat]) categories[cat] = [];
  categories[cat].push(item);
});
for (const [cat, dishes] of Object.entries(categories)) {
  menu += `*${cat}*\n`;
  dishes.forEach(d => {
    menu += `  • ${d.name} — ${d.price}€\n`;
    if (d.description) menu += `    _${d.description}_\n`;
  });
  menu += '\n';
}
menu += '🌟 *Plat du jour :* à demander !\n\n📅 Vous souhaitez réserver une table ?';
return [{json: {phone: $('📊 Parser Message WA').first().json.phone, menu_text: menu}}];

let resp;
try {
  const raw = $input.first().json.message?.content || $input.first().json.choices?.[0]?.message?.content || '{}';
  resp = JSON.parse(raw);
} catch(e) {
  resp = {intent: 'other', response_fr: 'Merci pour votre message ! Marco vous répondra bientôt.', needs_human: true};
}
const phone = $('📊 Parser Message WA').first().json.phone;
return [{json: {...resp, phone}}];

