const c = $input.first().json.fields || $input.first().json;
const points = c.loyalty_points || 0;
const tier = c.loyalty_tier || 'Bronze';
const name = c.name || 'Client';

// Tier info
const tiers = {
  'Bronze': {emoji: '🥉', next: 'Silver', nextPts: 100, reward: '-10% 1 fois/mois'},
  'Silver': {emoji: '🥈', next: 'Gold', nextPts: 300, reward: 'Dessert offert à chaque visite'},
  'Gold':   {emoji: '🥇', next: 'VIP', nextPts: 600, reward: '-15% permanent + Table prioritaire'},
  'VIP':    {emoji: '💎', next: null, nextPts: null, reward: '-15% permanent + Table prioritaire + Surprise chef'},
};
const info = tiers[tier] || tiers['Bronze'];

// Progress bar
let bar = '';
if (info.nextPts) {
  const pct = Math.min(Math.round((points / info.nextPts) * 12), 12);
  bar = '█'.repeat(pct) + '░'.repeat(12 - pct) + ' ' + Math.round((points/info.nextPts)*100) + '%';
}

let msg = '🏆 Bonjour ' + name + ' !\n\n';
msg += 'Statut : ' + info.emoji + ' ' + tier + '\n';
msg += 'Points : ' + points;
if (info.nextPts) msg += ' / ' + info.nextPts + ' pour ' + info.next + ' ' + (tiers[info.next]?.emoji || '');
msg += '\n';
if (bar) msg += bar + '\n';
msg += '\n';
if (info.next) {
  msg += '🎁 Prochaine récompense : ' + tiers[info.next]?.reward + '\n';
} else {
  msg += '🎁 Votre récompense : ' + info.reward + '\n';
}
msg += '\n📅 Réserver ?  🎁 Mon parrainage';

const phone = $('📊 Extraire Téléphone').first().json.phone;
return [{json: {phone, message: msg, tier, points}}];

