const data = $input.first().json;
const tiers = {'Silver': '🥈', 'Gold': '🥇', 'VIP': '💎'};
const rewards = {
  'Silver': '-10% sur votre prochain repas !',
  'Gold': 'Un dessert offert à chaque visite !',
  'VIP': '-15% permanent + table prioritaire + surprise du chef !'
};
const emoji = tiers[data.new_tier] || '🏆';
const reward = rewards[data.new_tier] || 'Récompenses exclusives';
return [{json: {
  phone: data.phone,
  message: '🎉 Félicitations ' + (data.name || '') + ' !\n\nVous passez au statut ' + emoji + ' ' + data.new_tier + ' !\n\n🎁 Votre récompense : ' + reward + '\n\nMerci pour votre fidélité ! 🙏'
}}];

const msg = $input.first().json;
return [{json: {
  referrer_phone: msg.referrer_phone || '',
  new_phone: msg.new_customer_phone || msg.from || '',
  referral_code: msg.code || ''
}}];

const referrer = $input.first().json;
const newPts = (referrer.fields?.loyalty_points || 0) + 100;
return [{json: {id: referrer.id, loyalty_points: newPts, phone: referrer.fields?.phone}}];

const result = $input.first().json?.result || {};
const reviews = result.reviews || [];
const sixHoursAgo = Date.now() - (6 * 60 * 60 * 1000);

const newReviews = reviews.filter(r => {
  const reviewTime = r.time * 1000;
  return reviewTime > sixHoursAgo;
});

if (newReviews.length === 0) return [{json: {has_new: false}}];

return newReviews.map(r => ({json: {
  has_new: true,
  author: r.author_name,
  rating: r.rating,
  text: r.text || '',
  time: new Date(r.time * 1000).toISOString(),
  profile_url: r.author_url || '',
  relative_time: r.relative_time_description || ''
}}));

const raw = $input.first().json;
let response = '';
try {
  const content = raw.content || raw.choices?.[0]?.message?.content || '';
  if (typeof content === 'string') response = content;
  else if (Array.isArray(content)) response = content.map(c => c.text || '').join('');
} catch(e) { response = 'Merci beaucoup pour votre avis ! À bientôt chez La Tavola.'; }

const review = $('📊 Filtrer Nouveaux Avis').first().json;
return [{json: {
  author: review.author,
  rating: review.rating,
  text: review.text,
  draft_response: response
}}];

const raw = $input.first().json;
let response = '';
try {
  const content = raw.content || raw.choices?.[0]?.message?.content || '';
  if (typeof content === 'string') response = content;
  else if (Array.isArray(content)) response = content.map(c => c.text || '').join('');
} catch(e) { response = 'Merci pour votre retour, nous en prenons note.'; }
const review = $('📊 Filtrer Nouveaux Avis').first().json;
return [{json: {author: review.author, rating: review.rating, text: review.text, draft_response: response}}];

const raw = $input.first().json;
let response = '';
try {
  const content = raw.content || raw.choices?.[0]?.message?.content || '';
  if (typeof content === 'string') response = content;
  else if (Array.isArray(content)) response = content.map(c => c.text || '').join('');
} catch(e) { response = 'Nous sommes sincèrement désolés. Contactez-nous à latavola.lyon@gmail.com.'; }
const review = $('📊 Filtrer Nouveaux Avis').first().json;
return [{json: {author: review.author, rating: review.rating, text: review.text, draft_response: response}}];

const dates = [];
const now = new Date();
for (let i = 0; i < 7; i++) {
  const d = new Date(now);
  d.setDate(d.getDate() + i);
  dates.push({
    date: d.toISOString().split('T')[0],
    day_name: ['Dimanche','Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi'][d.getDay()],
    day_idx: d.getDay()
  });
}
return dates.map(d => ({json: d}));

const resas = $input.all().length;
const maxTables = 22; // 55 couverts / ~2.5 par table
const occupancy = Math.round((resas / maxTables) * 100);
const dayInfo = $('📋 Dates de la Semaine').first().json;
return [{json: {
  date: dayInfo.date,
  day_name: dayInfo.day_name,
  reservations: resas,
  max_tables: maxTables,
  occupancy_pct: occupancy,
  needs_promo: occupancy < 50
}}];

const data = $input.first().json;
return [{json: {
  target_date: data.date || '',
  target_day: data.day_name || '',
  promo_type: data.promo_type || 'discount_20',
  discount: data.discount || '20%',
  message_template: data.message || ''
}}];

const clients = $input.all();
const twoWeeksAgo = new Date();
twoWeeksAgo.setDate(twoWeeksAgo.getDate() - 14);

const eligible = clients.filter(c => {
  const f = c.json.fields || c.json;
  const lastPromo = f.last_promo_sent ? new Date(f.last_promo_sent) : new Date(0);
  return lastPromo < twoWeeksAgo;
}).slice(0, 50); // Max 50 messages per campaign

return eligible.length ? eligible : [{json: {skip: true}}];

let msg;
try {
  const raw = $input.first().json.message?.content || '{}';
  msg = JSON.parse(raw).message || 'Ce soir, -20% chez La Tavola ! 🍕 On vous garde une table ?';
} catch(e) {
  msg = 'Ce soir, -20% chez La Tavola ! 🍕 On vous garde une table ?';
}
const client = $('🔁 Envoyer à Chaque Client').first().json;
return [{json: {phone: client.fields?.phone || client.phone, message: msg}}];

const today = new Date().toISOString().split('T')[0];
const yesterday = new Date(Date.now() - 86400000).toISOString().split('T')[0];
const weekStart = new Date();
weekStart.setDate(weekStart.getDate() - weekStart.getDay() + 1);
return [{json: {today, yesterday, week_start: weekStart.toISOString().split('T')[0]}}];

// Collect all data from parallel branches
const today = $('📋 Date du Jour').first().json.today;

// Today's reservations
let resasToday;
try { resasToday = $('📅 Résas Aujourd\'hui').all(); } catch(e) { resasToday = []; }
const totalCovers = resasToday.reduce((sum, r) => {
  const ps = (r.json.fields || r.json).party_size || 2;
  return sum + ps;
}, 0);

// Yesterday's stats
let resasYest;
try { resasYest = $('📅 Résas Hier (Complétées)').all(); } catch(e) { resasYest = []; }
const yestRevenue = resasYest.reduce((sum, r) => {
  return sum + ((r.json.fields || r.json).total || 65);
}, 0);

// VIPs
let vips;
try { vips = $('👑 VIPs Aujourd\'hui').all(); } catch(e) { vips = []; }
const vipNames = vips.slice(0, 3).map(v => (v.json.fields || v.json).name || 'VIP').join(', ');

// Reviews
let reviews;
try { reviews = $('⭐ Avis Récents').all(); } catch(e) { reviews = []; }
const pendingReviews = reviews.length;

// Orders
let orders;
try { orders = $('🛒 Commandes en Attente').all(); } catch(e) { orders = []; }
const pendingOrders = orders.length;

// Day of week for context
const dayNames = ['Dimanche','Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi'];
const dayName = dayNames[new Date().getDay()];

return [{json: {
  today,
  day_name: dayName,
  resas_count: resasToday.length,
  total_covers: totalCovers,
  max_covers: 55,
  occupancy_pct: Math.round((totalCovers / 55) * 100),
  yest_revenue: yestRevenue,
  yest_resas: resasYest.length,
  vip_names: vipNames,
  vip_count: vips.length,
  pending_reviews: pendingReviews,
  pending_orders: pendingOrders,
}}];

let briefing;
try {
  const raw = $input.first().json.message?.content || '{}';
  briefing = JSON.parse(raw).briefing;
} catch(e) {
  // Fallback briefing
  const d = $('📊 Agréger Données').first().json;
  briefing = '☀️ Bonjour Marco !\n\n';
  briefing += '📅 Ce soir : ' + d.total_covers + '/' + d.max_covers + ' couverts (' + d.occupancy_pct + '%)\n';
  briefing += '💰 Hier : ' + d.yest_revenue + '€ (' + d.yest_resas + ' tables)\n';
  if (d.vip_count > 0) briefing += '👑 VIP : ' + d.vip_names + '\n';
  if (d.pending_reviews > 0) briefing += '⭐ ' + d.pending_reviews + ' avis en attente sur Slack\n';
  if (d.pending_orders > 0) briefing += '🛒 ' + d.pending_orders + ' commandes à préparer\n';
  briefing += '\nBonne journée ! 🍝';
}
return [{json: {briefing}}];

const now = new Date();
const weekStart = new Date(now);
weekStart.setDate(now.getDate() - 7);
return [{json: {
  week_start: weekStart.toISOString().split('T')[0],
  week_end: now.toISOString().split('T')[0]
}}];

const resas = $input.all();
const completed = resas.filter(r => (r.json.fields || r.json).status === 'Completed');
const noShows = resas.filter(r => (r.json.fields || r.json).status === 'No-Show');
const cancelled = resas.filter(r => (r.json.fields || r.json).status === 'Cancelled');

const totalRevenue = completed.reduce((s, r) => s + ((r.json.fields || r.json).total || 65), 0);
const totalCovers = completed.reduce((s, r) => s + ((r.json.fields || r.json).party_size || 2), 0);

// Day breakdown
const dayStats = {};
const dayNames = ['Dim','Lun','Mar','Mer','Jeu','Ven','Sam'];
completed.forEach(r => {
  const d = new Date((r.json.fields || r.json).date);
  const day = dayNames[d.getDay()];
  if (!dayStats[day]) dayStats[day] = {count: 0, revenue: 0};
  dayStats[day].count++;
  dayStats[day].revenue += (r.json.fields || r.json).total || 65;
});

return [{json: {
  total_reservations: resas.length,
  completed: completed.length,
  no_shows: noShows.length,
  cancelled: cancelled.length,
  total_revenue: totalRevenue,
  total_covers: totalCovers,
  avg_ticket: totalCovers > 0 ? Math.round(totalRevenue / totalCovers) : 0,
  no_show_rate: resas.length > 0 ? Math.round((noShows.length / resas.length) * 100) : 0,
  day_breakdown: JSON.stringify(dayStats),
  week_start: $('📋 Données de la Semaine').first().json.week_start,
  week_end: $('📋 Données de la Semaine').first().json.week_end
}}];

let report;
try {
  const raw = $input.first().json.message?.content || '{}';
  report = JSON.parse(raw).report;
} catch(e) {
  const d = $('📊 Stats Hebdo').first().json;
  report = '📊 Rapport Hebdo La Tavola\n';
  report += '💰 Revenue : ' + d.total_revenue + '€\n';
  report += '👥 Couverts : ' + d.total_covers + '\n';
  report += '🔴 No-shows : ' + d.no_shows + ' (' + d.no_show_rate + '%)\n';
  report += '📈 Ticket moyen : ' + d.avg_ticket + '€';
}
return [{json: {report}}];
